#!/usr/bin/env python3
"""Regenerate tests/common/api.rs from the PNG_EXPORT/PNG_EXPORTA declarations
in c_src/include/png.h.  Run from the repository root:

    python3 translation/tests/gen_api.py > translation/tests/common/api.rs
"""
import re
import sys

HEADER = '''//! Resolved symbol tables for the two shared libraries.
//!
//! Every public entry point declared with `PNG_EXPORT` / `PNG_EXPORTA` in
//! `c_src/include/png.h` is looked up by name in BOTH `.so` files.  Building an
//! `Api` therefore also proves the symbol is present and callable in both.
//!
//! GENERATED by `tests/gen_api.py` -- do not hand-edit.
#![allow(dead_code)]
#![allow(non_snake_case)]

use super::*;
use libloading::Library;
use std::ffi::{c_char, c_double, c_int, c_long, c_uint, c_void};
'''

FOOTER = '''
/// The two symbol tables, resolved once.
pub struct Both {
    pub c: Api,
    pub rs: Api,
}

pub fn apis() -> &'static Both {
    use std::sync::OnceLock;
    static B: OnceLock<Both> = OnceLock::new();
    B.get_or_init(|| {
        let l = libs();
        Both {
            c: Api::new(&l.c),
            rs: Api::new(&l.rs),
        }
    })
}

/// Iterate over `(label, api)` for both libraries, C first.
pub fn each() -> [(&'static str, &'static Api); 2] {
    let b = apis();
    [("C", &b.c), ("RUST", &b.rs)]
}
'''

TM = [
    ("png_const_structrp", "png_structp"), ("png_const_structp", "png_structp"),
    ("png_structrp", "png_structp"), ("png_structp", "png_structp"),
    ("png_structpp", "*mut png_structp"),
    ("png_const_inforp", "png_infop"), ("png_const_infop", "png_infop"),
    ("png_inforp", "png_infop"), ("png_infop", "png_infop"),
    ("png_infopp", "*mut png_infop"),
    ("png_imagep", "*mut png_image"),
    ("png_const_bytep", "*const png_byte"), ("png_bytepp", "*mut *mut png_byte"),
    ("png_bytep *", "*mut *mut png_byte"), ("png_bytepp *", "*mut *mut *mut png_byte"),
    ("png_bytep", "*mut png_byte"),
    ("png_const_charp", "*const c_char"), ("png_charpp *", "*mut *mut *mut c_char"),
    ("png_charpp", "*mut *mut c_char"), ("png_charp *", "*mut *mut c_char"),
    ("png_charp", "*mut c_char"),
    ("png_const_colorp", "*const png_color"), ("png_colorp *", "*mut *mut png_color"),
    ("png_colorp", "*mut png_color"),
    ("png_const_color_8p", "*const png_color_8"), ("png_color_8p *", "*mut *mut png_color_8"),
    ("png_color_8p", "*mut png_color_8"),
    ("png_const_color_16p", "*const png_color_16"),
    ("png_color_16p *", "*mut *mut png_color_16"), ("png_color_16p", "*mut png_color_16"),
    ("png_const_timep", "*const png_time"), ("png_timep *", "*mut *mut png_time"),
    ("png_timep", "*mut png_time"),
    ("png_const_textp", "*const png_text"), ("png_textp *", "*mut *mut png_text"),
    ("png_textp", "*mut png_text"),
    ("png_sPLT_tpp", "*mut *mut png_sPLT_t"), ("png_const_sPLT_tp", "*const png_sPLT_t"),
    ("png_unknown_chunkpp", "*mut *mut png_unknown_chunk"),
    ("png_const_unknown_chunkp", "*const png_unknown_chunk"),
    ("png_const_uint_16p", "*const png_uint_16"), ("png_uint_16p *", "*mut *mut png_uint_16"),
    ("png_uint_16p", "*mut png_uint_16"), ("png_uint_16", "png_uint_16"),
    ("png_const_voidp", "*const c_void"), ("png_voidp", "*mut c_void"),
    ("png_uint_32p", "*mut png_uint_32"), ("png_uint_32 *", "*mut png_uint_32"),
    ("png_uint_32", "png_uint_32"),
    ("png_int_32 *", "*mut png_int_32"), ("png_int_32", "png_int_32"),
    ("png_alloc_size_t * PNG_RESTRICT", "*mut usize"), ("png_alloc_size_t", "usize"),
    ("png_const_fixed_point_p", "*const png_fixed_point"),
    ("png_fixed_point *", "*mut png_fixed_point"), ("png_fixed_point", "png_fixed_point"),
    ("png_const_doublep", "*const c_double"),
    ("png_byte", "png_byte"),
    ("png_error_ptr", "png_error_ptr"), ("png_rw_ptr", "png_rw_ptr"),
    ("png_flush_ptr", "png_flush_ptr"),
    ("png_read_status_ptr", "png_read_status_ptr"),
    ("png_write_status_ptr", "png_write_status_ptr"),
    ("png_progressive_info_ptr", "png_progressive_info_ptr"),
    ("png_progressive_row_ptr", "png_progressive_row_ptr"),
    ("png_progressive_end_ptr", "png_progressive_end_ptr"),
    ("png_user_transform_ptr", "png_user_transform_ptr"),
    ("png_user_chunk_ptr", "png_user_chunk_ptr"),
    ("png_longjmp_ptr", "png_longjmp_ptr"), ("png_malloc_ptr", "png_malloc_ptr"),
    ("png_free_ptr", "png_free_ptr"),
    ("const struct tm *", "*const c_void"), ("time_t", "c_long"),
    ("FILE *", "*mut c_void"),
    ("const char *", "*const c_char"), ("char out[29]", "*mut c_char"),
    ("const void *", "*const c_void"), ("void *", "*mut c_void"),
    ("size_t *", "*mut usize"), ("size_t", "usize"),
    ("double *", "*mut c_double"), ("double", "c_double"),
    ("float", "f32"),
    ("int *", "*mut c_int"), ("int", "c_int"),
    ("jmp_buf*", "*mut c_void"),
    ("unsigned int", "c_uint"),
    ("void", "()"),
]
D = dict(TM)


def conv(t):
    t = " ".join(t.strip().split())
    if t in D:
        return D[t]
    raise SystemExit("UNMAPPED TYPE: %r" % t)


def split_arg(a):
    a = " ".join(a.strip().split())
    if a == "void":
        return None
    if a == "char out[29]":
        return "*mut c_char"
    if a in D:
        return D[a]
    m = re.match(r"^(.*?)([A-Za-z_][A-Za-z0-9_]*)$", a)
    if not m:
        raise SystemExit("bad arg %r" % a)
    head = m.group(1)
    if head.strip() == "":
        raise SystemExit("UNMAPPED %r" % a)
    return conv(head)


def decls(path):
    src = open(path).read()
    src = re.sub(r"/\*.*?\*/", "", src, flags=re.S)
    out = {}
    pat = re.compile(
        r"PNG_(?:FP_|FIXED_)?EXPORT\s*\(\s*\d+\s*,\s*([A-Za-z_][A-Za-z0-9_ *]*?)\s*,"
        r"\s*(\w+)\s*,\s*\((.*?)\)\s*\)",
        re.S,
    )
    for m in pat.finditer(src):
        out[m.group(2)] = (" ".join(m.group(1).split()), " ".join(m.group(3).split()))
    pata = re.compile(
        r"PNG_EXPORTA\s*\(\s*\d+\s*,\s*([A-Za-z_][A-Za-z0-9_ *]*?)\s*,\s*(\w+)\s*,\s*\((.*?)\)\s*,",
        re.S,
    )
    for m in pata.finditer(src):
        out[m.group(2)] = (" ".join(m.group(1).split()), " ".join(m.group(3).split()))
    return out


# Declared in png.h but compiled out of this build (absent from both `.so`s):
#   png_err                     -- PNG_ERROR_TEXT_SUPPORTED is on, so png_err
#                                  is only declared for the !ERROR_TEXT case
#   png_set_strip_error_numbers -- PNG_ERROR_NUMBERS_SUPPORTED is off
NOT_EXPORTED = {"png_err", "png_set_strip_error_numbers"}


# Symbols the C `.so` exports that are declared in pngpriv.h rather than png.h
# (PNG_INTERNAL_FUNCTION).  Only the ones the tests drive directly are listed.
EXTRA = {
    "png_set_text_2": ("int", "png_const_structrp png_ptr, png_inforp info_ptr, png_const_textp text_ptr, int num_text"),
    "png_reset_crc": ("void", "png_structrp png_ptr"),
    "png_calculate_crc": ("void", "png_structrp png_ptr, png_const_bytep ptr, size_t length"),
    "png_zstream_error": ("void", "png_structrp png_ptr, int ret"),
    "png_muldiv": ("int", "png_fixed_point *res, png_fixed_point a, png_int_32 multiplied_by, png_int_32 divided_by"),
    "png_reciprocal": ("png_fixed_point", "png_fixed_point a"),
    "png_reciprocal2": ("png_fixed_point", "png_fixed_point a, png_fixed_point b"),
    "png_gamma_significant": ("int", "png_fixed_point gamma_value"),
    "png_gamma_8bit_correct": ("png_byte", "unsigned int value, png_fixed_point gamma_value"),
    "png_gamma_16bit_correct": ("png_uint_16", "unsigned int value, png_fixed_point gamma_value"),
    "png_gamma_correct": ("png_uint_16", "png_structrp png_ptr, unsigned int value, png_fixed_point gamma_value"),
    "png_safecat": ("size_t", "png_charp buffer, size_t bufsize, size_t pos, png_const_charp string"),
    "png_format_number": ("png_charp", "png_const_charp start, png_charp end, int format, png_alloc_size_t number"),
    "png_check_fp_number": ("int", "png_const_charp string, size_t size, int *statep, size_t *whereami"),
    "png_check_fp_string": ("int", "png_const_charp string, size_t size"),
    "png_ascii_from_fp": ("void", "png_const_structrp png_ptr, png_charp ascii, size_t size, double fp, unsigned int precision"),
    "png_ascii_from_fixed": ("void", "png_const_structrp png_ptr, png_charp ascii, size_t size, png_fixed_point fp"),
    "png_fixed": ("png_fixed_point", "png_const_structrp png_ptr, double fp, png_const_charp text"),
    "png_fixed_ITU": ("png_uint_32", "png_const_structrp png_ptr, double fp, png_const_charp text"),
    "png_build_grayscale_palette": ("void", "int bit_depth, png_colorp palette"),
    "png_check_IHDR": ("void", "png_const_structrp png_ptr, png_uint_32 width, png_uint_32 height, int bit_depth, int color_type, int interlace_type, int compression_type, int filter_type"),
    "png_check_keyword": ("png_uint_32", "png_structrp png_ptr, png_const_charp key, png_bytep new_key"),
    "png_chunk_unknown_handling": ("int", "png_const_structrp png_ptr, png_uint_32 chunk_name"),
    "png_handle_as_unknown": ("int", "png_const_structrp png_ptr, png_const_bytep chunk_name"),
    "png_reset_zstream": ("int", "png_structrp png_ptr"),
    "png_malloc_base": ("png_voidp", "png_const_structrp png_ptr, png_alloc_size_t size"),
    "png_malloc_array": ("png_voidp", "png_const_structrp png_ptr, int nelements, size_t element_size"),
    "png_realloc_array": ("png_voidp", "png_const_structrp png_ptr, png_const_voidp array, int old_elements, int add_elements, size_t element_size"),
    "png_free_buffer_list": ("void", "png_structrp png_ptr, png_voidp list"),
    "png_zalloc": ("png_voidp", "png_voidp png_ptr, unsigned int items, unsigned int size"),
    "png_zfree": ("void", "png_voidp png_ptr, png_voidp ptr"),
    "png_XYZ_from_xy": ("int", "png_voidp XYZ, png_const_voidp xy"),
    "png_xy_from_XYZ": ("int", "png_voidp xy, png_const_voidp XYZ"),
    "png_safe_error": ("void", "png_structp png_ptr, png_const_charp error_message"),
    "png_safe_warning": ("void", "png_structp png_ptr, png_const_charp warning_message"),
    "png_user_version_check": ("int", "png_structrp png_ptr, png_const_charp user_png_ver"),
    "png_image_error": ("int", "png_imagep image, png_const_charp error_message"),
    "png_warning_parameter": ("void", "png_voidp p, int number, png_const_charp string"),
    "png_warning_parameter_unsigned": ("void", "png_voidp p, int number, int format, png_alloc_size_t value"),
    "png_warning_parameter_signed": ("void", "png_voidp p, int number, int format, png_int_32 value"),
    "png_formatted_warning": ("void", "png_const_structrp png_ptr, png_voidp p, png_const_charp message"),
    "png_default_read_data": ("void", "png_structp png_ptr, png_bytep data, size_t length"),
    "png_default_write_data": ("void", "png_structp png_ptr, png_bytep data, size_t length"),
    "png_default_flush": ("void", "png_structp png_ptr"),
    "png_read_data": ("void", "png_structrp png_ptr, png_bytep data, size_t length"),
    "png_write_data": ("void", "png_structrp png_ptr, png_const_bytep data, size_t length"),
    "png_flush": ("void", "png_structrp png_ptr"),
    "png_read_sig": ("void", "png_structrp png_ptr, png_inforp info_ptr"),
    "png_read_chunk_header": ("png_uint_32", "png_structrp png_ptr"),
    "png_crc_read": ("void", "png_structrp png_ptr, png_bytep buf, png_uint_32 length"),
    "png_crc_finish": ("int", "png_structrp png_ptr, png_uint_32 skip"),
    "png_set_invalid": ("void", "png_const_structrp png_ptr, png_inforp info_ptr, int mask"),
    "png_free_jmpbuf": ("void", "png_structrp png_ptr"),
    "png_destroy_png_struct": ("void", "png_structrp png_ptr"),
    "png_create_png_struct": ("png_structp", "png_const_charp user_png_ver, png_voidp error_ptr, png_error_ptr error_fn, png_error_ptr warn_fn, png_voidp mem_ptr, png_malloc_ptr malloc_fn, png_free_ptr free_fn"),
    "png_get_signature": ("png_const_bytep", "png_const_structrp png_ptr, png_const_inforp info_ptr"),
    "png_resolve_file_gamma": ("png_fixed_point", "png_structrp png_ptr"),
}


def main():
    d = decls("c_src/include/png.h")
    for k, v in EXTRA.items():
        d.setdefault(k, v)
    fields = []
    for name in sorted(d):
        if name in NOT_EXPORTED:
            continue
        ret, args = d[name]
        args = args.strip()
        if args.startswith("(") and args.endswith(")"):
            args = args[1:-1]
        parts, depth, cur = [], 0, ""
        for ch in args:
            if ch == "(":
                depth += 1
            if ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        if cur.strip():
            parts.append(cur)
        rargs = [c for c in (split_arg(p) for p in parts) if c is not None]
        rret = conv(ret)
        sig = 'unsafe extern "C" fn(%s)' % ", ".join(rargs)
        if rret != "()":
            sig += " -> %s" % rret
        fields.append((name, sig))

    w = sys.stdout.write
    w(HEADER)
    w("\npub struct Api {\n")
    for n, s in fields:
        w("    pub %s: %s,\n" % (n, s))
    w("}\n\nimpl Api {\n    pub fn new(lib: &'static Library) -> Api {\n        Api {\n")
    for n, s in fields:
        w('            %s: sym::<%s>(lib, "%s"),\n' % (n, s, n))
    w("        }\n    }\n}\n")
    w(FOOTER)


if __name__ == "__main__":
    main()
